import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
print("user_version:", con.execute("PRAGMA user_version").fetchone()[0])
tabs = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
views = [v for (v,) in con.execute("select name from sqlite_master where type='view' order by name")]
print(f"tables: {len(tabs)}  views: {len(views)}")
rows = {}
for t in tabs:
    rows[t] = con.execute(f'select count(*) from "{t}"').fetchone()[0]
print("\n--- NON-EMPTY TABLES ---")
for t,n in sorted(rows.items(), key=lambda kv:-kv[1]):
    if n: print(f"{n:>7}  {t}")
print("\n--- EMPTY TABLES ---")
print("  ".join(t for t,n in sorted(rows.items()) if not n))
empty = {t for t,n in rows.items() if not n}
print("\n--- UNWRITABLE (NOT NULL FK -> empty table) ---")
for t in tabs:
    dead = {f[3] for f in con.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in dead and c[3]: print(f"  UNWRITABLE  {t}.{c[1]} -> {[f[2] for f in con.execute(f'PRAGMA foreign_key_list(\"{t}\")') if f[3]==c[1]]}")
